"""Detail pages art (your painted trophy room): background with the picture frame and stats panel, red button, gold stars, stone pedestal, gold divider.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# everything in info_bg.jpg pixels (1870 x 841)
ART_W, ART_H = 1870, 841
TITLE = (600, 64, 1268, 172)        # inside of the blank title plaque
LIGHTS = ((378, 120, 50), (1492, 120, 50))
PNG = {
  'gold_divider': ('png', ''),
  'gstar_half': ('png', ''),
  'gstar_off': ('png', ''),
  'gstar_on': ('png', ''),
  'info_bg': ('jpg', ''),
  'pedestal': ('png', ''),
  'red_button': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
